    <style>
        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            max-width: 1200px;
            margin: 0 auto;
            padding: 20px;
            line-height: 1.6;
            color: #111;
            background: #f8f9fa;
        }
        .page {
            page-break-after: always;
            margin-bottom: 40px;
        }
        /* Column detection */
        .columns {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: 30px;
            max-width: 900px;
            margin: 0 auto;
        }
        .columns .column {
            display: flex;
            flex-direction: column;
        }
        /* Heading hierarchy */
        h1 { font-size: 2.5em; margin-bottom: 0.5em; text-align: center; }
        h2 { font-size: 1.8em; margin-top: 1.5em; margin-bottom: 0.5em; }
        h3 { font-size: 1.4em; margin-top: 1.2em; margin-bottom: 0.4em; }
        /* Text blocks with spacing */
        p {
            margin: 0.8em 0;
            text-align: justify;
        }
        /* Lists */
        ul, ol {
            margin: 1em 0 1em 2em;
        }
        li {
            margin: 0.4em 0;
        }
        /* Inline elements */
        strong {
            font-weight: 700;
        }
        em {
            font-style: italic;
        }
        /* Placeholder for images/charts/diagrams */
        .placeholder {
            width: 100%;
            height: 300px;
            background: #e9ecef;
            border: 2px dashed #adb5bd;
            margin: 1.5em 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-family: monospace;
            color: #6c757d;
            font-size: 1.1em;
            text-align: center;
            position: relative;
        }
        .placeholder::after {
            content: "Diagram / Photo / Chart";
            position: absolute;
            bottom: 10px;
            font-size: 0.9em;
        }
        /* Signature area */
        .signature {
            width: 200px;
            height: 80px;
            border: 1px solid #333;
            margin: 2em auto;
            display: flex;
            align-items: center;
            justify-content: center;
            font-family: cursive;
            font-size: 1.3em;
            color: #333;
        }
        /* Footer / page number simulation */
        .page-number {
            text-align: center;
            font-size: 0.8em;
            color: #6c757d;
            margin-top: 30px;
        }
        /* Table support */
        table {
            width: 100%;
            border-collapse: collapse;
            margin: 1em 0;
        }
        th, td {
            border: 1px solid #333;
            padding: 8px;
            text-align: left;
        }
        th {
            background: #f0f0f0;
        }
        /* Unclear / illegible */
        .unclear {
            color: #dc3545;
            font-style: italic;
        }
    </style>
</head>
